package com.example.rokidgeminisecretary;
import org.json.*;import java.io.*;
/** Only this project's GitHub releases and exact APK filenames are eligible. */
public final class UpdatePolicy {
 public static final String CERT="4022edbcdf7973743f1fda819afd281f6fd4abd12e9886896206ac1e57a791d7",BASE="https://github.com/tenru-do/dennou-hisho-loki/releases/";
 public static JSONObject parse(JSONArray releases,long now)throws Exception{JSONObject latest=null;int highest=0;for(int i=0;i<releases.length();i++){JSONObject row=releases.getJSONObject(i);String tag=row.optString("tag_name");if(row.optBoolean("draft")||!tag.matches("glass-v[1-9][0-9]{0,5}"))continue;int version=Integer.parseInt(tag.substring(7));if(version>highest){highest=version;latest=row;}}if(latest==null)throw new IOException("確認できる配布版がありません");String tag="glass-v"+highest,link=BASE+"tag/"+tag;if(!link.equals(latest.optString("html_url")))throw new IOException("配布先のURLを確認できません");JSONObject out=new JSONObject().put("tag",tag).put("url",link).put("checkedAt",now).put("prerelease",latest.optBoolean("prerelease"));JSONArray assets=latest.getJSONArray("assets");int count=0;for(int i=0;i<assets.length();i++){JSONObject asset=assets.getJSONObject(i);String name=asset.optString("name");if(!name.matches("loki-(glass|phone)-v[1-9][0-9]{0,5}-release\\.apk"))continue;String app=name.contains("-glass-")?"glass":"phone";if(out.has(app))throw new IOException("同じ端末向けAPKが複数あります");int version=Integer.parseInt(name.split("-v")[1].split("-")[0]);if(app.equals("glass")&&version!=highest)throw new IOException("メガネの版番号が一致しません");String url=BASE+"download/"+tag+"/"+name,digest=asset.optString("digest");long size=asset.optLong("size");if(!url.equals(asset.optString("browser_download_url"))||!digest.matches("sha256:[a-f0-9]{64}")||size<1||size>2147483648L||!asset.optString("state").equals("uploaded"))throw new IOException("APKの公開情報を確認できません");out.put(app,new JSONObject().put("version",version).put("name",name).put("url",url).put("sha256",digest.substring(7)).put("bytes",size));count++;}if(count!=2)throw new IOException("メガネとスマホの両APKを確認できません");return out;}
 public static String compatibility(JSONObject identity){if(identity==null||identity.optLong("version")<1)return "端末の版・署名は未確認です";JSONArray certs=identity.optJSONArray("signingSha256");if(certs!=null&&certs.length()==1&&CERT.equals(certs.optString(0)))return "既存の配布署名版です。取得したAPKの署名を確認して上書き更新してください";if(identity.optBoolean("debuggable"))return "開発署名版です。配布APKへ切り替えるためにアンインストールしないでください";return "既存配布版との署名一致を確認できません。現在の導入元と更新経路を確認してください";}
 public static boolean newer(JSONObject release,JSONObject phone,JSONObject glass){if(release==null)return false;return phone!=null&&phone.optLong("version")>0&&release.optJSONObject("phone")!=null&&release.optJSONObject("phone").optLong("version")>phone.optLong("version")||glass!=null&&glass.optLong("version")>0&&release.optJSONObject("glass")!=null&&release.optJSONObject("glass").optLong("version")>glass.optLong("version");}
 private UpdatePolicy(){}
}
